BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第16條（育嬰留職停薪之申請資格、期間、合併計算及社會保險），最後修正公布日：第16條 2014-12-11，本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP104-1-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第17條（育嬰留職停薪期滿申請復職時，雇主得拒絕之事由，包括不可抗力暫停工作在一個月以上），最後修正公布日：第17條 2002-01-16（制定公布），本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP105-1-05','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第16條（育嬰留職停薪之申請資格、保險費，以及與收養兒童先行共同生活者亦得申請）及第2條（本法於公務人員、教育人員及軍職人員亦適用之）。第16條考試日後未再修正；第2條於 2023-08-16 修正，僅調整公務人員、教育人員及軍職人員不適用之條文，育嬰留職停薪之規定仍適用之，選項(C)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP105-1-06','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第15條（產假、產檢假及陪產假）、第18條（哺乳時間）及第20條（家庭照顧假）。考試時第15條規定產檢假五日、陪產假五日，第18條規定子女未滿一歲者每日另給哺乳時間二次、每次三十分鐘並視為工作時間；第15條於 2022-01-12 修正為產檢假七日、陪產檢及陪產假七日，第18條於 2016-05-18 修正為子女未滿二歲者每日另給哺（集）乳時間六十分鐘。依現行條文，選項(A)亦屬錯誤，選項(D)仍錯誤。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP106-1-16','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第16條（育嬰留職停薪之申請資格、保險費之免繳與遞延，以及津貼之發放另以法律定之），最後修正公布日：第16條 2014-12-11，本題考試日 2017-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP106-2-13','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第20條（家庭照顧假）及第22條。考試時第22條規定受僱者之配偶未就業者，不適用第16條及第20條之規定（有正當理由者除外），選項(D)錯誤；第22條已於 2022-01-12 刪除（2022-01-18 施行），配偶未就業之受僱者亦得請家庭照顧假，依現行條文選項(D)已非錯誤。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP106-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第16條（育嬰留職停薪之申請資格（任職滿六個月）、合併計算及保險費），最後修正公布日：第16條 2014-12-11，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP107-1-05','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第16條，以及就業保險法第11條、第19條之2：性別平等工作法第16條規定育嬰留職停薪津貼之發放另以法律定之，由就業保險法第11條、第19條之2規定請領條件及給付。性別平等工作法第16條考試日後未再修正；就業保險法第19條之2 於 2022-01-12 修正，仍規定育嬰留職停薪津貼，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP107-1-16','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第1條及第12條：受僱者於執行職務時遭上司以考績及續聘為條件要求交往，屬第12條所定之性騷擾。2023-08-16 修正第1條，明定工作場所性騷擾事件除校園性騷擾事件外依本法處理；第12條同日修正（部分項次自 2024-03-08 施行），增訂權勢性騷擾之定義。本題情形仍適用本法（官方答案 B、C 均給分）。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP107-1-29','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第15條。考試時規定產假八星期、妊娠三個月以上流產者產假四星期、產檢假五日、陪產假五日；2022-01-12 修正為產檢假七日、陪產檢及陪產假七日。依現行條文，選項(C)「產檢假5日」及選項(D)「陪產假5日」亦屬錯誤，選項(B)仍錯誤。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP107-2-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第14條（生理假）、第18條（哺（集）乳時間）、第19條（撫育未滿三歲子女減少工作時間，減少之工作時間不得請求報酬）及第20條（家庭照顧假）。第14條、第18條、第20條考試日後未再修正；第19條於 2022-01-12 修正，增訂受僱於僱用未滿三十人雇主之受僱者經協商合意後亦得適用，減少之工作時間不得請求報酬之規定未變，選項(A)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP108-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-01-19。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第14條（生理假）、第15條（陪產假）、第19條（減少或調整工作時間）及第20條（家庭照顧假）。第14條、第20條考試日後未再修正；第15條於 2022-01-12 修正，陪產假由五日改為陪產檢及陪產假七日，選項(B)「3日」於考試時及現行規定下均錯誤；第19條同日修正，增訂受僱於僱用未滿三十人雇主之受僱者經協商合意亦得適用，選項(C)所述受僱於僱用三十人以上雇主之受僱者得請求減少或調整工作時間仍屬正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP108-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第15條（產假）。第15條於 2022-01-12 修正，產檢假由五日改為七日、陪產假改為陪產檢及陪產假七日，產假八星期、妊娠三個月以上流產者四星期、二個月以上未滿三個月者一星期、未滿二個月者五日之規定未變，選項(B)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP109-1-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第20條、第21條（家庭照顧假之事由，以及雇主不得拒絕、不得視為缺勤而影響全勤獎金），最後修正公布日：第20條 2011-01-05、第21條 2008-01-16，本題考試日 2020-02-15 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP109-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第14條（生理假）、第15條（產假八星期）、第18條（哺（集）乳時間六十分鐘）及第19條（每天減少工作時間一小時）。第14條、第18條考試日後未再修正；第15條於 2022-01-12 修正產檢假及陪產假日數，產假八星期未變；第19條同日修正，增訂僱用未滿三十人雇主之受僱者經協商合意亦得適用，每天減少工作時間一小時之規定未變，選項(D)「二小時」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP110-2-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第2條（雇主與受僱者之約定優於本法者從其約定、本法於公務人員教育人員及軍職人員亦適用、技術生除建教生外亦適用、實習生遭受性騷擾時適用本法）。第2條於 2023-08-16 修正，僅調整公務人員、教育人員及軍職人員不適用之條文，選項(A)(B)(C)之內容未變，選項(D)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP111-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第17條（育嬰留職停薪期滿申請復職時，雇主得拒絕之事由），最後修正公布日：第17條 2002-01-16（制定公布），本題考試日 2022-07-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP112-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-07-29。本題考性別平等工作法（考試時名稱為性別工作平等法，2023-08-16 更名）第27條（性騷擾之損害賠償）。第27條於 2023-08-16 修正，增訂權勢性騷擾之懲罰性賠償金等，雇主與行為人連帶賠償、雇主舉證免責、雇主對性騷擾行為人之求償權及到庭期間給予公假之規定未變，選項(C)「無求償權」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>18 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>18 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'95a63048d659af612247ea7851fe9cda' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_15, count(*) FILTER (WHERE q.legal_status='changed') changed_3, count(*) total_18 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
